// Überschriften werden nie abgeschnitten: was nicht in die Zeile passt, wird kleiner
function passen(root = document) {
  const rand = document.documentElement.clientWidth - 6;
  $$('h1, h2, .h-xl, .h-l', root).forEach(el => {
    if (el.closest('.band, .tafel, .lookbook')) return;
    el.style.fontSize = '';
    const box = el.getBoundingClientRect(); if (!box.width) return;
    const cs = getComputedStyle(el), fs = parseFloat(cs.fontSize), schraeg = cs.fontStyle === 'italic' ? fs * 0.12 : 0;   // kursive Buchstaben ragen rechts über
    const teile = [...el.querySelectorAll('.wz > span, em, b')].map(x => x.getBoundingClientRect().right + schraeg);
    let clip = rand; for (let x = el.parentElement; x && x !== document.body; x = x.parentElement) { if (getComputedStyle(x).overflowX !== 'visible') { clip = Math.min(clip, x.getBoundingClientRect().right - 2); break; } }
    const rechts = Math.max(box.left + el.scrollWidth, ...teile), grenze = clip;
    if (rechts <= grenze) return;
    const f = (grenze - box.left) / (rechts - box.left);
    el.style.fontSize = Math.max(fs * 0.5, fs * f * 0.97) + 'px';
  });
}
{ let t; addEventListener('resize', () => { clearTimeout(t); t = setTimeout(() => passen($('#haupt') || document), 150); }); if (document.fonts && document.fonts.ready) document.fonts.ready.then(() => passen($('#haupt') || document)); }
