const abgemeldetHtml = () => `<p class="kicker" style="margin-bottom:18px">Newsletter</p><h1 class="h-l">Du bist abgemeldet.</h1><p class="lead" style="margin-top:16px">Schade, aber klar. Du bekommst von uns keine Neuigkeiten mehr. Wenn du es dir anders überlegst: <a href="${U('dabei')}" data-link>hier wieder eintragen</a>.</p>`;
